/// Project module configuration
///
/// Use the builder pattern to configure and register this module:
///
/// ```text
/// let project = ProjectModule::builder()
///     .with_database(pool.clone())
///     .build()?;
///
/// // Unguarded full CRUD (trusted/admin); compose a guarded router for production.
/// let router = project.all_crud_routes();
/// ```
pub struct ProjectModule {
    pub(crate) activity_type_service: Arc<ActivityTypeService>,
    pub(crate) project_service: Arc<ProjectService>,
    pub(crate) project_template_service: Arc<ProjectTemplateService>,
    pub(crate) project_template_task_service: Arc<ProjectTemplateTaskService>,
    pub(crate) task_service: Arc<TaskService>,
    /// The module's extension state (`lib.ext.rs`); its fields read through `Deref`.
    pub(crate) ext: ModuleExt,
}

impl std::ops::Deref for ProjectModule {
    type Target = ModuleExt;
    fn deref(&self) -> &Self::Target {
        &self.ext
    }
}

impl std::ops::DerefMut for ProjectModule {
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut self.ext
    }
}

/// What the extension's `build` hook receives from the generated build (ADR-0031).
#[allow(dead_code)]
pub(crate) struct ModuleParts<'a> {
    pub(crate) db_pool: &'a PgPool,
    pub(crate) activity_type_service: &'a Arc<ActivityTypeService>,
    pub(crate) activity_type_repository: &'a Arc<ActivityTypeRepository>,
    pub(crate) project_service: &'a Arc<ProjectService>,
    pub(crate) project_repository: &'a Arc<ProjectRepository>,
    pub(crate) project_template_service: &'a Arc<ProjectTemplateService>,
    pub(crate) project_template_repository: &'a Arc<ProjectTemplateRepository>,
    pub(crate) project_template_task_service: &'a Arc<ProjectTemplateTaskService>,
    pub(crate) project_template_task_repository: &'a Arc<ProjectTemplateTaskRepository>,
    pub(crate) task_service: &'a Arc<TaskService>,
    pub(crate) task_repository: &'a Arc<TaskRepository>,
}

impl ProjectModule {
    /// Create a new module builder
    pub fn builder() -> ProjectModuleBuilder {
        ProjectModuleBuilder::new()
    }

    /// Mount ALL generated CRUD endpoints (12 per entity) with NO domain
    /// validation — the fully **unguarded** surface. A well-formed request can
    /// create invalid rows or soft-delete a referenced master out from under its
    /// dependents. Prefer a guarded composition (read + validated writes) for any
    /// real deployment; use this only in trusted/admin/seeding contexts.
    pub fn all_crud_routes(&self) -> Router {
        use presentation::http::{
            create_activity_type_routes,
            create_project_routes,
            create_project_template_routes,
            create_project_template_task_routes,
            create_task_routes,
        };

        Router::new()
            .merge(create_activity_type_routes(self.activity_type_service.clone()))
            .merge(create_project_routes(self.project_service.clone()))
            .merge(create_project_template_routes(self.project_template_service.clone()))
            .merge(create_project_template_task_routes(self.project_template_task_service.clone()))
            .merge(create_task_routes(self.task_service.clone()))
    }

    /// Deprecated alias for [`Self::all_crud_routes`]. `routes()` reads like
    /// "the routes" but mounts UNVALIDATED generic CRUD on every entity — a naive
    /// mount exposes unguarded writes. Compose a guarded router (read + validated
    /// writes) for production, or call `all_crud_routes()` to opt into the full
    /// unguarded surface explicitly.
    #[deprecated(note = "mounts unvalidated generic CRUD; prefer readonly_routes() + validated writes, or all_crud_routes() for the full/unguarded surface")]
    pub fn routes(&self) -> Router {
        self.all_crud_routes()
    }

    /// Read-only routes for every entity (GET endpoints only) — the safe base.
    ///
    /// Generic mutation can't reach here, so this surface cannot bypass a
    /// validated write service's invariants. Use this as the production base and
    /// merge validated write routes (or a write service's HTTP layer) onto it.
    pub fn readonly_routes(&self) -> Router {
        use presentation::http::{
            create_activity_type_read_routes,
            create_project_read_routes,
            create_project_template_read_routes,
            create_project_template_task_read_routes,
            create_task_read_routes,
        };

        Router::new()
            .merge(create_activity_type_read_routes(self.activity_type_service.clone()))
            .merge(create_project_read_routes(self.project_service.clone()))
            .merge(create_project_template_read_routes(self.project_template_service.clone()))
            .merge(create_project_template_task_read_routes(self.project_template_task_service.clone()))
            .merge(create_task_read_routes(self.task_service.clone()))
    }

}

/// Builder for ProjectModule
pub struct ProjectModuleBuilder {
    db_pool: Option<PgPool>,
    /// The builder's extension state (`lib.ext.rs`); its fields read through `Deref`.
    ext: ModuleBuilderExt,
}

impl std::ops::Deref for ProjectModuleBuilder {
    type Target = ModuleBuilderExt;
    fn deref(&self) -> &Self::Target {
        &self.ext
    }
}

impl std::ops::DerefMut for ProjectModuleBuilder {
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut self.ext
    }
}

impl ProjectModuleBuilder {
    /// Create a new builder
    pub fn new() -> Self {
        Self {
            db_pool: None,
            ext: Default::default(),
        }
    }

    /// Set the database connection pool
    pub fn with_database(mut self, pool: PgPool) -> Self {
        self.db_pool = Some(pool);
        self
    }


    /// Build the module with configured dependencies
    pub fn build(self) -> anyhow::Result<ProjectModule> {
        let db_pool = self.db_pool
            .ok_or_else(|| anyhow::anyhow!("Database pool not configured"))?;

        // ActivityType service
        let activity_type_repository = Arc::new(ActivityTypeRepository::new(db_pool.clone()));
        let activity_type_service = Arc::new(ActivityTypeService::with_repository(activity_type_repository.clone()));

        // Project service
        let project_repository = Arc::new(ProjectRepository::new(db_pool.clone()));
        let project_service = Arc::new(ProjectService::with_repository(project_repository.clone()));

        // ProjectTemplate service
        let project_template_repository = Arc::new(ProjectTemplateRepository::new(db_pool.clone()));
        let project_template_service = Arc::new(ProjectTemplateService::with_repository(project_template_repository.clone()));

        // ProjectTemplateTask service
        let project_template_task_repository = Arc::new(ProjectTemplateTaskRepository::new(db_pool.clone()));
        let project_template_task_service = Arc::new(ProjectTemplateTaskService::with_repository(project_template_task_repository.clone()));

        // Task service
        let task_repository = Arc::new(TaskRepository::new(db_pool.clone()));
        let task_service = Arc::new(TaskService::with_repository(task_repository.clone()));


        // The extension builds its own state from what the generated build made.
        let ext = self.ext.build(&ModuleParts {
            db_pool: &db_pool,
            activity_type_service: &activity_type_service,
            activity_type_repository: &activity_type_repository,
            project_service: &project_service,
            project_repository: &project_repository,
            project_template_service: &project_template_service,
            project_template_repository: &project_template_repository,
            project_template_task_service: &project_template_task_service,
            project_template_task_repository: &project_template_task_repository,
            task_service: &task_service,
            task_repository: &task_repository,
        })?;

        Ok(ProjectModule {
            activity_type_service,
            project_service,
            project_template_service,
            project_template_task_service,
            task_service,
            ext,
        })
    }
}

impl Default for ProjectModuleBuilder {
    fn default() -> Self {
        Self::new()
    }
}
